window.READING_REVIEW_DATA={"title":"Survivor’s Story","items":[{"id":"story-300a2b876d8f","term":"fauna","type":"word","ipa":"ˈfɔːnə","pos":"n. 名词","stars":3,"zh":"动物群","contextSenses":[0],"legacyId":"fauna|动物群","note":"常见义：某地区的动物总称；学习用法：flora and fauna 植物群与动物群；辨析：不可将 fauna 单独理解成鸟类，后文才限定鸟类占主导","examples":[{"en":"As an island country with a fauna dominated by birds, New Zealand was once home to an owl species which is now extinct, the laughing owl, named for its distinctive cry.","zh":"新西兰是一个鸟类占动物群主体的岛国，那里曾生活着一种如今已经灭绝的猫头鹰——笑鸮，它因独特的叫声而得名。","sourceId":"A1","source":"original","number":1,"paragraph":"A"}],"para":"A"},{"id":"story-0b437aa4ed96","term":"extinct","type":"word","ipa":"ɪkˈstɪŋkt","pos":"adj. 形容词","stars":4,"zh":"已经灭绝的","contextSenses":[0],"legacyId":"extinct|已经灭绝的","note":"常见义：灭绝的；不复存在的；学习用法：extinct species 灭绝物种；辨析：区别 endangered 濒危，濒危不等于已灭绝","examples":[{"en":"As an island country with a fauna dominated by birds, New Zealand was once home to an owl species which is now extinct, the laughing owl, named for its distinctive cry.","zh":"新西兰是一个鸟类占动物群主体的岛国，那里曾生活着一种如今已经灭绝的猫头鹰——笑鸮，它因独特的叫声而得名。","sourceId":"A1","source":"original","number":1,"paragraph":"A"}],"para":"A","memory":{"method":"词族联想","parts":"extinct（灭绝的）→ extinction（灭绝）","tip":"整个物种消失才 extinct；不等于个体死亡。","family":"extinction 灭绝；extant 现存的"}},{"id":"story-ab114938aefd","term":"distinctive","type":"word","ipa":"dɪˈstɪŋktɪv","pos":"adj. 形容词","stars":4,"zh":"独特且易辨认的","contextSenses":[0],"legacyId":"distinctive|独特且易辨认的","note":"常见义：有特色的；独特的；学习用法：distinctive feature 鲜明特征；辨析：distinct 可指清楚的或不同的，不完全相同","examples":[{"en":"As an island country with a fauna dominated by birds, New Zealand was once home to an owl species which is now extinct, the laughing owl, named for its distinctive cry.","zh":"新西兰是一个鸟类占动物群主体的岛国，那里曾生活着一种如今已经灭绝的猫头鹰——笑鸮，它因独特的叫声而得名。","sourceId":"A1","source":"original","number":1,"paragraph":"A"}],"para":"A","memory":{"method":"后缀构词","parts":"distinct（明显不同的）＋-ive","tip":"某种特征独特，容易将其辨认出来。","family":"distinct 明显不同的；distinction 差别"}},{"id":"story-bc81af2c7542","term":"widespread","type":"word","ipa":"ˈwaɪdspred","pos":"adj. 形容词","stars":3,"zh":"广泛分布的","contextSenses":[0],"legacyId":"widespread|广泛分布的","note":"常见义：分布广的；普遍的；学习用法：widespread use/concern 广泛使用或普遍担忧；辨析：不是保证每一个地点都有","examples":[{"en":"This bird was widespread throughout the islands when European settlers arrived in the middle of the 19th century and it remained in good numbers for some years thereafter.","zh":"十九世纪中叶欧洲移民到来时，这种鸟广泛分布于各岛，之后的若干年里数量仍然可观。","sourceId":"A2","source":"original","number":2,"paragraph":"A"}],"para":"A"},{"id":"story-03c78f24f50e","term":"thereafter","type":"word","ipa":"ˌðeərˈɑːftə","pos":"adv. 副词","stars":3,"zh":"此后","contextSenses":[0],"legacyId":"thereafter|此后","note":"常见义：从那以后；学习用法：正式叙述中的之后；辨析：指欧洲移民到来之后，不是灭绝之后","examples":[{"en":"This bird was widespread throughout the islands when European settlers arrived in the middle of the 19th century and it remained in good numbers for some years thereafter.","zh":"十九世纪中叶欧洲移民到来时，这种鸟广泛分布于各岛，之后的若干年里数量仍然可观。","sourceId":"A2","source":"original","number":2,"paragraph":"A"}],"para":"A"},{"id":"story-a5e4126e9a6b","term":"in good numbers","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"数量可观","contextSenses":[0],"legacyId":"in good numbers|数量可观","note":"常见义：数量充足；学习用法：阅读识别种群数量描述；辨析：good 修饰数量状况，不是评价鸟的品德","examples":[{"en":"This bird was widespread throughout the islands when European settlers arrived in the middle of the 19th century and it remained in good numbers for some years thereafter.","zh":"十九世纪中叶欧洲移民到来时，这种鸟广泛分布于各岛，之后的若干年里数量仍然可观。","sourceId":"A2","source":"original","number":2,"paragraph":"A"}],"para":"A"},{"id":"story-1e927485e151","term":"predation","type":"word","ipa":"prɪˈdeɪʃən","pos":"n. 名词","stars":4,"zh":"捕食","contextSenses":[0],"legacyId":"predation|捕食","note":"常见义：捕食行为；学习用法：predation by… 被……捕食；predator 捕食者；辨析：不是一般竞争或抢夺","examples":[{"en":"Where other native birds suffered from predation by the Polynesian rat, the laughing owl turned the tables and adapted its diet to include the rodent.","zh":"其他本土鸟类遭受波利尼西亚鼠捕食时，笑鸮却扭转了局面，调整食谱，把这种啮齿动物也纳入了猎物。","sourceId":"A3","source":"original","number":3,"paragraph":"A"}],"para":"A","memory":{"method":"词族变化","parts":"predation（捕食行为）↔ predator（捕食者）","tip":"同一生态事件：行为是 predation，行动者是 predator。","family":"predator 捕食者；prey 猎物"}},{"id":"story-4c74ad64b990","term":"turn the tables","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"扭转局面，反过来占优势","contextSenses":[0],"legacyId":"turn the tables|扭转局面，反过来占优势","note":"常见义：反败为胜；逆转形势；学习用法：口语描述局势逆转；辨析：不是移动桌子；本句从可能被害转为捕食鼠类","examples":[{"en":"Where other native birds suffered from predation by the Polynesian rat, the laughing owl turned the tables and adapted its diet to include the rodent.","zh":"其他本土鸟类遭受波利尼西亚鼠捕食时，笑鸮却扭转了局面，调整食谱，把这种啮齿动物也纳入了猎物。","sourceId":"A3","source":"original","number":3,"paragraph":"A"}],"para":"A"},{"id":"story-90367a576afc","term":"adapt","type":"word","ipa":"əˈdæpt","pos":"v. 动词","stars":4,"zh":"调整食性以适应","contextSenses":[0],"legacyId":"adapt|调整食性以适应","note":"常见义：适应；改编；调整；学习用法：adapt to 环境适应；adapt sth 调整某物；辨析：这里有宾语 its diet，不是 adopt 采纳","examples":[{"en":"Where other native birds suffered from predation by the Polynesian rat, the laughing owl turned the tables and adapted its diet to include the rodent.","zh":"其他本土鸟类遭受波利尼西亚鼠捕食时，笑鸮却扭转了局面，调整食谱，把这种啮齿动物也纳入了猎物。","sourceId":"A3","source":"original","number":3,"paragraph":"A"}],"para":"A","memory":{"method":"词族联想","parts":"adapt（适应、调整）→ adaptation（适应）","tip":"本文是调整食谱；区别 adopt（采纳）。","family":"adaptation 适应；adaptable 适应性强的"}},{"id":"story-fa98f565021b","term":"be capable of","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"有能力","contextSenses":[0],"legacyId":"be capable of|有能力","note":"常见义：能够胜任或做到；学习用法：capable of doing 有能力做；辨析：of 后接动名词，不接动词原形","examples":[{"en":"It was also capable of catching and killing the other New Zealand owl, the morepork, and even larger birds, such as the weka.","zh":"它还能捕捉并杀死新西兰另一种猫头鹰 morepork，甚至捕食更大的鸟，例如 weka。","sourceId":"A4","source":"original","number":4,"paragraph":"A"}],"para":"A"},{"id":"story-4932d1ef1a58","term":"catch","type":"word","ipa":"kætʃ","pos":"v. 动词","stars":2,"zh":"捕获猎物","contextSenses":[0],"legacyId":"catch|捕获猎物","note":"常见义：抓住；赶上；捕获；学习用法：catch prey 捕获猎物；catch a train 赶上火车；辨析：catch a cold 患感冒；catch someone’s attention 吸引注意","examples":[{"en":"It was also capable of catching and killing the other New Zealand owl, the morepork, and even larger birds, such as the weka.","zh":"它还能捕捉并杀死新西兰另一种猫头鹰 morepork，甚至捕食更大的鸟，例如 weka。","sourceId":"A4","source":"original","number":4,"paragraph":"A"}],"para":"A"},{"id":"story-b26fc4b7127c","term":"wipe out","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"使灭绝，彻底消除","contextSenses":[0],"legacyId":"wipe out|使灭绝，彻底消除","note":"常见义：消灭；摧毁；学习用法：物种被消灭；灾害摧毁；辨析：不只是用布擦掉","examples":[{"en":"However, the laughing owl was wiped out around the beginning of the 20th century, its demise caused by specimen collectors, habitat changes, and non-native predators including cats and stoats.","zh":"然而，笑鸮在二十世纪初前后灭绝了，它的消亡由标本采集者、栖息地变化，以及包括猫和白鼬在内的非本土捕食者造成。","sourceId":"A5","source":"original","number":5,"paragraph":"A"}],"para":"A"},{"id":"story-2cfc647af8d6","term":"demise","type":"word","ipa":"dɪˈmaɪz","pos":"n. 名词","stars":3,"zh":"消亡","contextSenses":[0],"legacyId":"demise|消亡","note":"常见义：死亡；终结；学习用法：物种消失；机构衰落或终结；辨析：较正式语体；口语通常用 disappearance 或 death","examples":[{"en":"However, the laughing owl was wiped out around the beginning of the 20th century, its demise caused by specimen collectors, habitat changes, and non-native predators including cats and stoats.","zh":"然而，笑鸮在二十世纪初前后灭绝了，它的消亡由标本采集者、栖息地变化，以及包括猫和白鼬在内的非本土捕食者造成。","sourceId":"A5","source":"original","number":5,"paragraph":"A"}],"para":"A"},{"id":"story-81df28f034e5","term":"specimen","type":"word","ipa":"ˈspesɪmən","pos":"n. 名词","stars":3,"zh":"采集的标本","contextSenses":[0],"legacyId":"specimen|采集的标本","note":"常见义：样本；标本；学习用法：生物或实验样本；辨析：本句 collectors 指采集标本者，不是收集邮票者","examples":[{"en":"However, the laughing owl was wiped out around the beginning of the 20th century, its demise caused by specimen collectors, habitat changes, and non-native predators including cats and stoats.","zh":"然而，笑鸮在二十世纪初前后灭绝了，它的消亡由标本采集者、栖息地变化，以及包括猫和白鼬在内的非本土捕食者造成。","sourceId":"A5","source":"original","number":5,"paragraph":"A"}],"para":"A"},{"id":"story-d92d2af07b8d","term":"manage to","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"成功做到了","contextSenses":[0],"legacyId":"manage to|成功做到了","note":"常见义：设法完成；学习用法：manage to survive 成功存活；辨析：含最终成功之意；不等于 merely try 尝试","examples":[{"en":"Surprisingly, it is the smaller owl, the morepork, that has managed to survive until this day.","zh":"令人意外的是，成功存活至今的反而是体型较小的猫头鹰 morepork。","sourceId":"A6","source":"original","number":6,"paragraph":"A"}],"para":"A"},{"id":"story-ced3b44c0bc9","term":"survive","type":"word","ipa":"səˈvaɪv","pos":"v. 动词","stars":3,"zh":"存活下来","contextSenses":[0],"legacyId":"survive|存活下来","note":"常见义：幸存；继续存在；学习用法：物种生存；在困难中坚持；辨析：survive 是存活，thrive 是良好发展","examples":[{"en":"Surprisingly, it is the smaller owl, the morepork, that has managed to survive until this day.","zh":"令人意外的是，成功存活至今的反而是体型较小的猫头鹰 morepork。","sourceId":"A6","source":"original","number":6,"paragraph":"A"}],"para":"A"},{"id":"story-d45e3315820c","term":"smaller","type":"word","ipa":"ˈsmɔːlə","pos":"adj. 形容词","stars":1,"zh":"相对笑鸮更小的","contextSenses":[0],"legacyId":"smaller|相对笑鸮更小的","note":"常见义：更小的；学习用法：比较级体现隐含对照；辨析：比较对象可由上下文提供，不必出现 than","examples":[{"en":"Surprisingly, it is the smaller owl, the morepork, that has managed to survive until this day.","zh":"令人意外的是，成功存活至今的反而是体型较小的猫头鹰 morepork。","sourceId":"A6","source":"original","number":6,"paragraph":"A"}],"para":"A"},{"id":"story-1e95ea93cdd6","term":"speckled","type":"word","ipa":"ˈspekəld","pos":"adj. 形容词","stars":3,"zh":"带斑点的","contextSenses":[0],"legacyId":"speckled|带斑点的","note":"常见义：有小斑点的；学习用法：描述外观的斑点特征；辨析：专业外观词，认读即可","examples":[{"en":"Speckled dark brown, with yellow eyes and long tails, they are around 29 centimetres long from head to tail and 175 grams in weight.","zh":"它们有带深棕色斑点的羽毛、黄色眼睛和长尾巴，从头到尾长约二十九厘米，重约一百七十五克。","sourceId":"B1","source":"original","number":7,"paragraph":"B"}],"para":"B"},{"id":"story-b34f362dfb49","term":"in weight","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"重量为","contextSenses":[0],"legacyId":"in weight|重量为","note":"常见义：就重量而言；学习用法：… grams in weight 重……克；辨析：不是增加体重的动作","examples":[{"en":"Speckled dark brown, with yellow eyes and long tails, they are around 29 centimetres long from head to tail and 175 grams in weight.","zh":"它们有带深棕色斑点的羽毛、黄色眼睛和长尾巴，从头到尾长约二十九厘米，重约一百七十五克。","sourceId":"B1","source":"original","number":7,"paragraph":"B"}],"para":"B"},{"id":"story-35959f62cd86","term":"fringe","type":"word","ipa":"frɪndʒ","pos":"n. 名词","stars":3,"zh":"羽毛边缘的流苏状结构","contextSenses":[0],"legacyId":"fringe|羽毛边缘的流苏状结构","note":"常见义：穗边；边缘；学习用法：on the fringe 边缘位置；fringe benefits 额外福利；辨析：不同语境可指非主流群体或刘海","examples":[{"en":"Moreporks have fringes on the edge of their feathers, so they can fly almost silently and not alert potential prey.","zh":"morepork 的羽毛边缘有流苏状结构，因此它们飞行时几乎无声，不会惊动潜在猎物。","sourceId":"B2","source":"original","number":8,"paragraph":"B"}],"para":"B"},{"id":"story-f2bcfd092c67","term":"alert","type":"word","ipa":"əˈlɜːt","pos":"v. 动词","stars":3,"zh":"使猎物警觉","contextSenses":[0],"legacyId":"alert|使猎物警觉","note":"常见义：提醒；使警惕；警觉的；学习用法：alert sb to danger 提醒某人危险；辨析：本句是动词；不是形容词“警觉的”","examples":[{"en":"Moreporks have fringes on the edge of their feathers, so they can fly almost silently and not alert potential prey.","zh":"morepork 的羽毛边缘有流苏状结构，因此它们飞行时几乎无声，不会惊动潜在猎物。","sourceId":"B2","source":"original","number":8,"paragraph":"B"}],"para":"B"},{"id":"story-cfa7bb43357c","term":"prey","type":"word","ipa":"preɪ","pos":"n. 名词","stars":2,"zh":"猎物","contextSenses":[0],"legacyId":"prey|猎物","note":"常见义：被捕食的动物；受害者；学习用法：predator and prey 捕食者与猎物；辨析：prey 通常集合式使用，非 pray 祈祷","examples":[{"en":"Moreporks have fringes on the edge of their feathers, so they can fly almost silently and not alert potential prey.","zh":"morepork 的羽毛边缘有流苏状结构，因此它们飞行时几乎无声，不会惊动潜在猎物。","sourceId":"B2","source":"original","number":8,"paragraph":"B"}],"para":"B"},{"id":"story-d6209d77a90b","term":"acute","type":"word","ipa":"əˈkjuːt","pos":"adj. 形容词","stars":4,"zh":"敏锐的","contextSenses":[0],"legacyId":"acute|敏锐的","note":"常见义：尖锐的；严重的；急性的；学习用法：acute hearing 敏锐听觉；acute shortage 严重短缺；辨析：acute illness 急性疾病，不能套到听觉上","examples":[{"en":"They have acute hearing and their large eyes are very sensitive to light.","zh":"它们听觉敏锐，大大的眼睛也对光线十分敏感。","sourceId":"B3","source":"original","number":9,"paragraph":"B"}],"para":"B","memory":{"method":"语义对比","parts":"整体记 acute；联记 acute hearing（敏锐的听觉）","tip":"本篇形容感官敏锐；医学中的急性是另一语境。","family":"acutely 敏锐地；acute hearing 敏锐的听觉"}},{"id":"story-23f4cb09ef94","term":"sensitive to","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"对光敏感","contextSenses":[0],"legacyId":"sensitive to|对光敏感","note":"常见义：敏感的；易受影响的；学习用法：sensitive to light/change 对光或变化敏感；辨析：sensible 是明智的，不能混用","examples":[{"en":"They have acute hearing and their large eyes are very sensitive to light.","zh":"它们听觉敏锐，大大的眼睛也对光线十分敏感。","sourceId":"B3","source":"original","number":9,"paragraph":"B"}],"para":"B"},{"id":"story-994438ba20ac","term":"hollow","type":"word","ipa":"ˈhɒləʊ","pos":"n. 名词","stars":3,"zh":"树洞","contextSenses":[0],"legacyId":"hollow|树洞","note":"常见义：中空的；洞穴；学习用法：tree hollow 树洞；hollow structure 中空结构；辨析：形容词 hollow promise 可指空洞承诺","examples":[{"en":"Moreporks nest in tree hollows, in clumps of plants, or in cavities among rocks and roots.","zh":"morepork 在树洞、植物丛，或岩石与树根之间的洞穴中筑巢。","sourceId":"C1","source":"original","number":10,"paragraph":"C"}],"para":"C"},{"id":"story-68427473eb4a","term":"nest","type":"word","ipa":"nest","pos":"v. 动词","stars":2,"zh":"筑巢","contextSenses":[0],"legacyId":"nest|筑巢","note":"常见义：巢；筑巢；学习用法：nesting sites 筑巢地点；辨析：本句 nest 为动词，不是一个名词主语","examples":[{"en":"Moreporks nest in tree hollows, in clumps of plants, or in cavities among rocks and roots.","zh":"morepork 在树洞、植物丛，或岩石与树根之间的洞穴中筑巢。","sourceId":"C1","source":"original","number":10,"paragraph":"C"}],"para":"C"},{"id":"story-2a3950e1f925","term":"ample","type":"word","ipa":"ˈæmpəl","pos":"adj. 形容词","stars":4,"zh":"充足的","contextSenses":[0],"legacyId":"ample|充足的","note":"常见义：足够且有余的；学习用法：ample evidence/time 充分证据或充裕时间；辨析：比仅仅 barely enough 更充足","examples":[{"en":"In the wild, moreporks usually start nesting in October, although two specimens have been recorded nesting in mid-winter, possibly stimulated by an ample food supply.","zh":"在野外，morepork 通常十月开始筑巢；不过，有记录显示两个个体在隆冬筑巢，可能是受到充足食物供应的促使。","sourceId":"C2","source":"original","number":11,"paragraph":"C"}],"para":"C","memory":{"method":"词族联想","parts":"ample（充足的）与 amply（充分地）联记","tip":"食物供应足够丰富：an ample food supply。","family":"amply 充分地；ample time 充足时间"}},{"id":"story-1788064d617f","term":"stimulate","type":"word","ipa":"ˈstɪmjʊleɪt","pos":"v.","stars":4,"zh":"促使开始筑巢","contextSenses":[0],"legacyId":"stimulate|促使开始筑巢","note":"常见义：刺激；促进；学习用法：stimulate growth/demand 促进增长或需求；辨析：本句不是医学电刺激","examples":[{"en":"In the wild, moreporks usually start nesting in October, although two specimens have been recorded nesting in mid-winter, possibly stimulated by an ample food supply.","zh":"在野外，morepork 通常十月开始筑巢；不过，有记录显示两个个体在隆冬筑巢，可能是受到充足食物供应的促使。","sourceId":"C2","source":"original","number":11,"paragraph":"C"}],"para":"C","memory":{"method":"构词／词族／搭配联想","parts":"stimulate → stimulation（刺激）","tip":"刺激感官 senses 帮助探索；与 simulate（模拟）区分。","family":"stimulation 刺激；stimulus 刺激物"}},{"id":"story-1c2eed424018","term":"record","type":"word","ipa":"rɪˈkɔːd","pos":"v. 动词","stars":3,"zh":"记录观察到的行为","contextSenses":[0],"legacyId":"record|记录观察到的行为","note":"常见义：记录；纪录；唱片；学习用法：record observations 记录观察；辨析：have been recorded doing 有记录表明正在做","examples":[{"en":"In the wild, moreporks usually start nesting in October, although two specimens have been recorded nesting in mid-winter, possibly stimulated by an ample food supply.","zh":"在野外，morepork 通常十月开始筑巢；不过，有记录显示两个个体在隆冬筑巢，可能是受到充足食物供应的促使。","sourceId":"C2","source":"original","number":11,"paragraph":"C"}],"para":"C"},{"id":"story-9b8ea791eed4","term":"lay","type":"word","ipa":"leɪ","pos":"v. 动词","stars":3,"zh":"产卵","contextSenses":[0],"legacyId":"lay|产卵","note":"常见义：放置；产卵；学习用法：lay eggs 下蛋；lay the foundation 奠定基础；辨析：lay 的过去式 laid，区别 lie 躺，其过去式 lay","examples":[{"en":"The female lays up to three white eggs, which she incubates for 20 to 30 days.","zh":"雌鸟最多产下三枚白色的卵，随后孵化二十到三十天。","sourceId":"C3","source":"original","number":12,"paragraph":"C"}],"para":"C"},{"id":"story-7eea2c40f0d5","term":"incubate","type":"word","ipa":"ˈɪŋkjʊbeɪt","pos":"v. 动词","stars":3,"zh":"孵卵","contextSenses":[0],"legacyId":"incubate|孵卵","note":"常见义：孵化；培育；学习用法：incubation period 孵化期或潜伏期；辨析：商业语境可指孵化创业项目","examples":[{"en":"The female lays up to three white eggs, which she incubates for 20 to 30 days.","zh":"雌鸟最多产下三枚白色的卵，随后孵化二十到三十天。","sourceId":"C3","source":"original","number":12,"paragraph":"C"}],"para":"C"},{"id":"story-ab1eddf118f0","term":"rarely","type":"word","ipa":"ˈreəli","pos":"adv. 副词","stars":3,"zh":"很少","contextSenses":[0],"legacyId":"rarely|很少","note":"常见义：不常；罕有；学习用法：表示低频；seldom 同义；辨析：不等于 never 从不","examples":[{"en":"During this time, she rarely hunts, and the male brings food to her.","zh":"在这段时间里，雌鸟很少捕猎，雄鸟会把食物带给它。","sourceId":"C4","source":"original","number":13,"paragraph":"C"}],"para":"C"},{"id":"story-d1a0a6cebe09","term":"male","type":"word","ipa":"meɪl","pos":"n. 名词","stars":2,"zh":"雄鸟","contextSenses":[0],"legacyId":"male|雄鸟","note":"常见义：雄性；男性；学习用法：male/female 动物性别；辨析：作为名词有时指雄性个体，不必译为男人","examples":[{"en":"During this time, she rarely hunts, and the male brings food to her.","zh":"在这段时间里，雌鸟很少捕猎，雄鸟会把食物带给它。","sourceId":"C4","source":"original","number":13,"paragraph":"C"}],"para":"C"},{"id":"story-bd5b1de46152","term":"hatch","type":"word","ipa":"hætʃ","pos":"v. 动词","stars":3,"zh":"孵化出壳","contextSenses":[0],"legacyId":"hatch|孵化出壳","note":"常见义：孵化；策划；学习用法：eggs/chicks hatch 卵孵化或雏鸟出壳；辨析：hatch a plan 可指策划；本句是生命过程","examples":[{"en":"Once the chicks hatch, she stays mainly on the nest until the young owls are fully feathered.","zh":"雏鸟一旦孵化，雌鸟就主要待在巢上，直到幼鸟羽毛完全长齐。","sourceId":"D1","source":"original","number":14,"paragraph":"D"}],"para":"D"},{"id":"story-f959e1404270","term":"feathered","type":"word","ipa":"ˈfeðəd","pos":"adj. 形容词","stars":3,"zh":"长有羽毛的，羽毛长齐的","contextSenses":[0],"legacyId":"feathered|长有羽毛的，羽毛长齐的","note":"常见义：有羽毛的；学习用法：fully feathered 羽毛完全长齐；辨析：feather one's nest 是谋私利，非本句","examples":[{"en":"Once the chicks hatch, she stays mainly on the nest until the young owls are fully feathered.","zh":"雏鸟一旦孵化，雌鸟就主要待在巢上，直到幼鸟羽毛完全长齐。","sourceId":"D1","source":"original","number":14,"paragraph":"D"}],"para":"D"},{"id":"story-da1109efc90c","term":"down","type":"word","ipa":"daʊn","pos":"n. 名词","stars":3,"zh":"绒毛","contextSenses":[0],"legacyId":"down|绒毛","note":"常见义：向下；下方；绒毛；学习用法：羽绒或鸟类绒毛；辨析：此处为名词，不是方向副词“向下”","examples":[{"en":"When hatched, chicks are covered in light grey down and have their eyes closed.","zh":"刚孵化时，雏鸟覆盖着浅灰色绒毛，眼睛闭着。","sourceId":"D2","source":"original","number":15,"paragraph":"D"}],"para":"D"},{"id":"story-c9cd2ea95f71","term":"closed","type":"word","ipa":"kləʊzd","pos":"adj. 形容词","stars":2,"zh":"闭着的","contextSenses":[0],"legacyId":"closed|闭着的","note":"常见义：关闭的；封闭的；学习用法：closed eyes 闭着的眼睛；辨析：不是表示 have closed 现在完成时","examples":[{"en":"When hatched, chicks are covered in light grey down and have their eyes closed.","zh":"刚孵化时，雏鸟覆盖着浅灰色绒毛，眼睛闭着。","sourceId":"D2","source":"original","number":15,"paragraph":"D"}],"para":"D"},{"id":"story-219e4577f000","term":"not until","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"直到……才","contextSenses":[0],"legacyId":"not until|直到……才","note":"常见义：延后至某时间才发生；学习用法：not… until… 常考时间边界；辨析：不是“到第八天都不睁眼”；第八天是开始点","examples":[{"en":"The eyes do not open until the eighth day after hatching.","zh":"它们要到孵化后的第八天才睁眼。","sourceId":"D3","source":"original","number":16,"paragraph":"D"}],"para":"D"},{"id":"story-6f7957cce5ef","term":"hatching","type":"word","ipa":"ˈhætʃɪŋ","pos":"n. 名词","stars":3,"zh":"孵化出壳这一过程","contextSenses":[0],"legacyId":"hatching|孵化出壳这一过程","note":"常见义：孵化；学习用法：after hatching 出壳后；辨析：after 后接动名词，不是另一个完整谓语","examples":[{"en":"The eyes do not open until the eighth day after hatching.","zh":"它们要到孵化后的第八天才睁眼。","sourceId":"D3","source":"original","number":16,"paragraph":"D"}],"para":"D"},{"id":"story-9432f40059e0","term":"around","type":"word","ipa":"əˈraʊnd","pos":"adv. 副词","stars":1,"zh":"大约","contextSenses":[0],"legacyId":"around|大约","note":"常见义：围绕；在附近；约；学习用法：约数；around 35 days 约35天；辨析：此处不是空间围绕","examples":[{"en":"They can fly at around 35 days.","zh":"它们大约在三十五日龄时就能飞行。","sourceId":"D4","source":"original","number":17,"paragraph":"D"}],"para":"D"},{"id":"story-20dea2abb39b","term":"can","type":"word","ipa":"kæn","pos":"modal v. 情态动词","stars":1,"zh":"具备飞行能力","contextSenses":[0],"legacyId":"can|具备飞行能力","note":"常见义：能；可以；学习用法：能力或可能性；辨析：can 不意味着当天每只鸟都一定飞行","examples":[{"en":"They can fly at around 35 days.","zh":"它们大约在三十五日龄时就能飞行。","sourceId":"D4","source":"original","number":17,"paragraph":"D"}],"para":"D"},{"id":"story-9b9888223661","term":"roost","type":"word","ipa":"ruːst","pos":"n. 名词","stars":3,"zh":"鸟的栖息处","contextSenses":[0],"legacyId":"roost|鸟的栖息处","note":"常见义：栖息处；栖息；学习用法：鸟类休息位置；辨析：不必等于繁殖用的 nest 巢","examples":[{"en":"By day, moreporks sleep in roosts.","zh":"白天，morepork 在栖息处睡觉。","sourceId":"E1","source":"original","number":18,"paragraph":"E"}],"para":"E"},{"id":"story-fb75094b4e41","term":"by day","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"在白天","contextSenses":[0],"legacyId":"by day|在白天","note":"常见义：白天时；学习用法：by day/by night 昼夜对照；辨析：by 在这里不是“通过”某种手段","examples":[{"en":"By day, moreporks sleep in roosts.","zh":"白天，morepork 在栖息处睡觉。","sourceId":"E1","source":"original","number":18,"paragraph":"E"}],"para":"E"},{"id":"story-36d3df5e78ba","term":"invertebrate","type":"word","ipa":"ɪnˈvɜːtɪbrət","pos":"n. 名词","stars":5,"zh":"无脊椎动物","contextSenses":[0],"legacyId":"invertebrate|无脊椎动物","note":"常见义：没有脊柱的动物；学习用法：生态阅读分类词；辨析：vertebrate 为脊椎动物，in- 为否定","examples":[{"en":"By night, they hunt a variety of animals – mainly large invertebrates including scarab and huhu beetles, moths, caterpillars and spiders.","zh":"夜晚，它们捕食多种动物，主要是大型无脊椎动物，包括金龟子、huhu 甲虫、蛾、毛毛虫和蜘蛛。","sourceId":"E2","source":"original","number":19,"paragraph":"E"}],"para":"E","memory":{"method":"否定前缀","parts":"in-（不、无）＋vertebrate（脊椎动物）","tip":"没有脊椎的动物；与 vertebrate 成对记。","family":"vertebrate 脊椎动物；invertebrate 无脊椎动物"}},{"id":"story-263fa73fbab9","term":"mainly","type":"word","ipa":"ˈmeɪnli","pos":"adv. 副词","stars":3,"zh":"主要是","contextSenses":[0],"legacyId":"mainly|主要是","note":"常见义：大部分地；主要地；学习用法：mostly/principally 的替换；辨析：不是 only 只，仅捕食这一类","examples":[{"en":"By night, they hunt a variety of animals – mainly large invertebrates including scarab and huhu beetles, moths, caterpillars and spiders.","zh":"夜晚，它们捕食多种动物，主要是大型无脊椎动物，包括金龟子、huhu 甲虫、蛾、毛毛虫和蜘蛛。","sourceId":"E2","source":"original","number":19,"paragraph":"E"}],"para":"E"},{"id":"story-c061fcc037e8","term":"take","type":"word","ipa":"teɪk","pos":"v. 动词","stars":1,"zh":"捕食，捕获","contextSenses":[0],"legacyId":"take|捕食，捕获","note":"常见义：拿；接受；花费；学习用法：take prey 捕获猎物；take time 花时间；辨析：本句不能直译成“拿走小鸟”","examples":[{"en":"They also take small birds and mice.","zh":"它们也捕食小鸟和老鼠。","sourceId":"E3","source":"original","number":20,"paragraph":"E"}],"para":"E"},{"id":"story-1433b8a2faea","term":"also","type":"word","ipa":"ˈɔːlsəʊ","pos":"adv. 副词","stars":1,"zh":"也","contextSenses":[0],"legacyId":"also|也","note":"常见义：此外；同样；学习用法：增加另一类信息；辨析：说明前一句“主要无脊椎动物”仍允许其他食物","examples":[{"en":"They also take small birds and mice.","zh":"它们也捕食小鸟和老鼠。","sourceId":"E3","source":"original","number":20,"paragraph":"E"}],"para":"E"},{"id":"story-4ffe26584bed","term":"as well as","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"也，还包括","contextSenses":[0],"legacyId":"as well as|也，还包括","note":"常见义：除……之外还；学习用法：A as well as B A与B都包含；辨析：不能理解成 A 比 B 更好","examples":[{"en":"They can find suitable food in pine forest as well as native forest.","zh":"它们既能在松林中，也能在本土森林中找到合适的食物。","sourceId":"E4","source":"original","number":21,"paragraph":"E"}],"para":"E"},{"id":"story-5e4d3c20eb31","term":"suitable","type":"word","ipa":"ˈsuːtəbəl","pos":"adj. 形容词","stars":3,"zh":"合适的","contextSenses":[0],"legacyId":"suitable|合适的","note":"常见义：适宜的；学习用法：suitable habitat/food 适宜栖息地或食物；辨析：suitable for + 名词，不等于一定最优","examples":[{"en":"They can find suitable food in pine forest as well as native forest.","zh":"它们既能在松林中，也能在本土森林中找到合适的食物。","sourceId":"E4","source":"original","number":21,"paragraph":"E"}],"para":"E"},{"id":"story-717054063314","term":"stun","type":"word","ipa":"stʌn","pos":"v. 动词","stars":3,"zh":"击晕","contextSenses":[0],"legacyId":"stun|击晕","note":"常见义：使昏迷；使震惊；学习用法：捕食时击晕；be stunned by 因……震惊；辨析：这里为实际失去反应，不是感到惊讶","examples":[{"en":"A morepork uses its sharp talons to catch or stun its prey, which it then carries away in its bill.","zh":"一只 morepork 用锋利的爪子抓住或击晕猎物，随后用喙把猎物叼走。","sourceId":"E5","source":"original","number":22,"paragraph":"E"}],"para":"E"},{"id":"story-9c422556dc81","term":"bill","type":"word","ipa":"bɪl","pos":"n. 名词","stars":2,"zh":"鸟喙","contextSenses":[0],"legacyId":"bill|鸟喙","note":"常见义：账单；法案；鸟喙；学习用法：beak 鸟喙为同义词；辨析：不是用账单把猎物带走","examples":[{"en":"A morepork uses its sharp talons to catch or stun its prey, which it then carries away in its bill.","zh":"一只 morepork 用锋利的爪子抓住或击晕猎物，随后用喙把猎物叼走。","sourceId":"E5","source":"original","number":22,"paragraph":"E"}],"para":"E"},{"id":"story-dac8f366abda","term":"talon","type":"word","ipa":"ˈtælən","pos":"n. 名词","stars":3,"zh":"猛禽的爪","contextSenses":[0],"legacyId":"talon|猛禽的爪","note":"常见义：爪，尤其猛禽利爪；学习用法：外貌和捕猎定位词；辨析：认读为主，普通爪可用 claw","examples":[{"en":"A morepork uses its sharp talons to catch or stun its prey, which it then carries away in its bill.","zh":"一只 morepork 用锋利的爪子抓住或击晕猎物，随后用喙把猎物叼走。","sourceId":"E5","source":"original","number":22,"paragraph":"E"}],"para":"E"},{"id":"story-e7b39725e150","term":"end up as","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"最终成为","contextSenses":[0],"legacyId":"end up as|最终成为","note":"常见义：以某种状态告终；学习用法：end up doing 最后做；end up in 最终处于；辨析：常带出乎意料的结果，不是“结束某物”","examples":[{"en":"Moreporks are clever hunters, and birds such as robins, grey warblers and fantails can end up as their prey.","zh":"morepork 是善于捕猎的鸟，知更鸟、灰莺、扇尾鹟等鸟类都可能最终成为它们的猎物。","sourceId":"E6","source":"original","number":23,"paragraph":"E"}],"para":"E"},{"id":"story-a4334a8ede43","term":"clever","type":"word","ipa":"ˈklevə","pos":"adj. 形容词","stars":2,"zh":"捕猎技巧高明的","contextSenses":[0],"legacyId":"clever|捕猎技巧高明的","note":"常见义：聪明的；巧妙的；学习用法：clever solution 巧妙方案；辨析：这里是行为能力评价，不能据此推断某项智力测试结果","examples":[{"en":"Moreporks are clever hunters, and birds such as robins, grey warblers and fantails can end up as their prey.","zh":"morepork 是善于捕猎的鸟，知更鸟、灰莺、扇尾鹟等鸟类都可能最终成为它们的猎物。","sourceId":"E6","source":"original","number":23,"paragraph":"E"}],"para":"E"},{"id":"story-0087a66ee267","term":"mob","type":"word","ipa":"mɒb","pos":"v. 动词","stars":3,"zh":"集群围攻","contextSenses":[0],"legacyId":"mob|集群围攻","note":"常见义：人群；围攻；群聚骚扰；学习用法：鸟类 mob 捕食者；mobbing 集群骚扰；辨析：此处作动词，不是黑帮名词","examples":[{"en":"In the day, these small birds sometimes mob drowsy moreporks and chase them away from their roosts; they force the sleepy predators to search for a more peaceful spot.","zh":"白天，这些小鸟有时会集群围攻昏昏欲睡的 morepork，把它们赶离栖息处，迫使这些困倦的捕食者寻找更安静的地方。","sourceId":"E7","source":"original","number":24,"paragraph":"E"}],"para":"E"},{"id":"story-9111a8a8536a","term":"drowsy","type":"word","ipa":"ˈdraʊzi","pos":"adj. 形容词","stars":3,"zh":"昏昏欲睡的","contextSenses":[0],"legacyId":"drowsy|昏昏欲睡的","note":"常见义：困倦的；学习用法：drowsy/sleepy 困倦；辨析：不是懒惰 lazy","examples":[{"en":"In the day, these small birds sometimes mob drowsy moreporks and chase them away from their roosts; they force the sleepy predators to search for a more peaceful spot.","zh":"白天，这些小鸟有时会集群围攻昏昏欲睡的 morepork，把它们赶离栖息处，迫使这些困倦的捕食者寻找更安静的地方。","sourceId":"E7","source":"original","number":24,"paragraph":"E"}],"para":"E"},{"id":"story-9772f019826b","term":"chase away","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"追赶，驱走","contextSenses":[0],"legacyId":"chase away|追赶，驱走","note":"常见义：赶走；学习用法：drive away 同义替换；辨析：away 表离开原地点","examples":[{"en":"In the day, these small birds sometimes mob drowsy moreporks and chase them away from their roosts; they force the sleepy predators to search for a more peaceful spot.","zh":"白天，这些小鸟有时会集群围攻昏昏欲睡的 morepork，把它们赶离栖息处，迫使这些困倦的捕食者寻找更安静的地方。","sourceId":"E7","source":"original","number":24,"paragraph":"E"}],"para":"E"},{"id":"story-0186942dee1c","term":"prove to be","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"结果证明是","contextSenses":[0],"legacyId":"prove to be|结果证明是","note":"常见义：被证实为；学习用法：prove to be effective 证明有效；辨析：不是 prove to do 的任意替换；此处带系表成分","examples":[{"en":"Moreporks have proved to be ungracious hosts.","zh":"事实证明，morepork 并不是好客的主人。","sourceId":"F1","source":"original","number":25,"paragraph":"F"}],"para":"F"},{"id":"story-d5761892facc","term":"host","type":"word","ipa":"həʊst","pos":"n. 名词","stars":2,"zh":"主人，原居此地的鸟","contextSenses":[0],"legacyId":"host|主人，原居此地的鸟","note":"常见义：主人；主持人；宿主；学习用法：生态宿主；活动主办方；辨析：此处把原居鸟拟人化为主人；不是网站主机","examples":[{"en":"Moreporks have proved to be ungracious hosts.","zh":"事实证明，morepork 并不是好客的主人。","sourceId":"F1","source":"original","number":25,"paragraph":"F"}],"para":"F"},{"id":"story-fd966e866359","term":"establish a population","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"建立一个种群","contextSenses":[0],"legacyId":"establish a population|建立一个种群","note":"常见义：建立稳定的群体；学习用法：生态保护或物种引入；辨析：population 在此是鸟的种群，不是人类人口","examples":[{"en":"Scientists trying to establish a population of plovers on Motuora Island in New Zealand’s Hauraki Gulf were mystified as to why only two birds survived out of the 75 placed there.","zh":"科学家试图在新西兰豪拉基湾的莫图奥拉岛建立一个鸻类种群；他们不解的是，放到那里的七十五只鸟为何只有两只存活。","sourceId":"F2","source":"original","number":26,"paragraph":"F"}],"para":"F"},{"id":"story-b58921e0461d","term":"mystified","type":"word","ipa":"ˈmɪstɪfaɪd","pos":"adj. 形容词","stars":3,"zh":"感到困惑不解","contextSenses":[0],"legacyId":"mystified|感到困惑不解","note":"常见义：迷惑的；不解的；学习用法：be puzzled about 对……困惑；辨析：不是神秘力量造成的","examples":[{"en":"Scientists trying to establish a population of plovers on Motuora Island in New Zealand’s Hauraki Gulf were mystified as to why only two birds survived out of the 75 placed there.","zh":"科学家试图在新西兰豪拉基湾的莫图奥拉岛建立一个鸻类种群；他们不解的是，放到那里的七十五只鸟为何只有两只存活。","sourceId":"F2","source":"original","number":26,"paragraph":"F"}],"para":"F"},{"id":"story-b9b9ba2fe020","term":"out of","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"在总数……中","contextSenses":[0],"legacyId":"out of|在总数……中","note":"常见义：从……里；总数中的；学习用法：two out of 75 七十五中的两只；辨析：比例范围，不是“两只飞出七十五只”","examples":[{"en":"Scientists trying to establish a population of plovers on Motuora Island in New Zealand’s Hauraki Gulf were mystified as to why only two birds survived out of the 75 placed there.","zh":"科学家试图在新西兰豪拉基湾的莫图奥拉岛建立一个鸻类种群；他们不解的是，放到那里的七十五只鸟为何只有两只存活。","sourceId":"F2","source":"original","number":26,"paragraph":"F"}],"para":"F"},{"id":"story-a4ad2ee25a8d","term":"culprit","type":"word","ipa":"ˈkʌlprɪt","pos":"n. 名词","stars":3,"zh":"造成问题的元凶","contextSenses":[0],"legacyId":"culprit|造成问题的元凶","note":"常见义：罪魁祸首；责任者；学习用法：the culprit behind… 问题原因；辨析：可用于无意行为或非人因素，不必真有犯罪","examples":[{"en":"The culprits turned out to be five pairs of moreporks that ate or chased away the new arrivals.","zh":"原来，罪魁祸首是五对 morepork，它们吃掉或赶走了这些新来的鸟。","sourceId":"F3","source":"original","number":27,"paragraph":"F"}],"para":"F"},{"id":"story-2984f2d42a38","term":"turn out to be","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"结果发现是","contextSenses":[0],"legacyId":"turn out to be|结果发现是","note":"常见义：原来是；最终证明是；学习用法：用于揭示结果；辨析：不是向外转身","examples":[{"en":"The culprits turned out to be five pairs of moreporks that ate or chased away the new arrivals.","zh":"原来，罪魁祸首是五对 morepork，它们吃掉或赶走了这些新来的鸟。","sourceId":"F3","source":"original","number":27,"paragraph":"F"}],"para":"F"},{"id":"story-40d58c97cde5","term":"arrival","type":"word","ipa":"əˈraɪvəl","pos":"n. 名词","stars":2,"zh":"新迁入的鸟","contextSenses":[0],"legacyId":"arrival|新迁入的鸟","note":"常见义：到达；新来者；学习用法：new arrivals 新到者；辨析：此处可数指个体，不仅是到达动作","examples":[{"en":"The culprits turned out to be five pairs of moreporks that ate or chased away the new arrivals.","zh":"原来，罪魁祸首是五对 morepork，它们吃掉或赶走了这些新来的鸟。","sourceId":"F3","source":"original","number":27,"paragraph":"F"}],"para":"F"},{"id":"story-e7ec8fba08de","term":"relatively","type":"word","ipa":"ˈrelətɪvli","pos":"adv. 副词","stars":3,"zh":"相对而言","contextSenses":[0],"legacyId":"relatively|相对而言","note":"常见义：比较地；相对地；学习用法：relatively common/costly 相对常见或昂贵；辨析：不是绝对“非常常见”","examples":[{"en":"Although moreporks are still considered to be relatively common, it is likely that numbers are in gradual decline due to predation and loss of habitat.","zh":"尽管 morepork 仍被认为比较常见，但它们的数量很可能正因捕食与栖息地丧失而逐渐下降。","sourceId":"G1","source":"original","number":28,"paragraph":"G"}],"para":"G"},{"id":"story-bf3047e7e75a","term":"decline","type":"word","ipa":"dɪˈklaɪn","pos":"n. 名词","stars":3,"zh":"数量下降","contextSenses":[0],"legacyId":"decline|数量下降","note":"常见义：减少；衰退；拒绝；学习用法：population decline 种群下降；辨析：动词 decline an invitation 是谢绝","examples":[{"en":"Although moreporks are still considered to be relatively common, it is likely that numbers are in gradual decline due to predation and loss of habitat.","zh":"尽管 morepork 仍被认为比较常见，但它们的数量很可能正因捕食与栖息地丧失而逐渐下降。","sourceId":"G1","source":"original","number":28,"paragraph":"G"}],"para":"G"},{"id":"story-f73c5cfc7343","term":"due to","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"由于","contextSenses":[0],"legacyId":"due to|由于","note":"常见义：由……引起；学习用法：引出原因；because of 同义；辨析：后接名词短语，不能直接套一个完整主谓句","examples":[{"en":"Although moreporks are still considered to be relatively common, it is likely that numbers are in gradual decline due to predation and loss of habitat.","zh":"尽管 morepork 仍被认为比较常见，但它们的数量很可能正因捕食与栖息地丧失而逐渐下降。","sourceId":"G1","source":"original","number":28,"paragraph":"G"}],"para":"G"},{"id":"story-58803e0b19b4","term":"vulnerable to","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"容易受到……伤害","contextSenses":[0],"legacyId":"vulnerable to|容易受到……伤害","note":"常见义：脆弱的；易受攻击的；学习用法：vulnerable to disease/climate change 易受疾病或气候变化影响；辨析：不是仅指情绪敏感","examples":[{"en":"As the female is a hole-nester, she is vulnerable to predators such as stoats and possums during the breeding season, and eggs and chicks will also be at risk from rats.","zh":"由于雌鸟在洞穴中筑巢，它在繁殖季节容易遭到白鼬和负鼠等捕食者袭击，卵和雏鸟也会受到鼠类威胁。","sourceId":"G2","source":"original","number":29,"paragraph":"G"}],"para":"G"},{"id":"story-fa65de0034e5","term":"at risk from","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"受到……的威胁","contextSenses":[0],"legacyId":"at risk from|受到……的威胁","note":"常见义：面临风险；学习用法：at risk of extinction 面临灭绝风险；辨析：from 后标风险来源；of 后常接风险事件","examples":[{"en":"As the female is a hole-nester, she is vulnerable to predators such as stoats and possums during the breeding season, and eggs and chicks will also be at risk from rats.","zh":"由于雌鸟在洞穴中筑巢，它在繁殖季节容易遭到白鼬和负鼠等捕食者袭击，卵和雏鸟也会受到鼠类威胁。","sourceId":"G2","source":"original","number":29,"paragraph":"G"}],"para":"G"},{"id":"story-cb2ed1f19678","term":"pesticide","type":"word","ipa":"ˈpestɪsaɪd","pos":"n. 名词","stars":4,"zh":"农药，杀虫杀有害生物药剂","contextSenses":[0],"legacyId":"pesticide|农药，杀虫杀有害生物药剂","note":"常见义：杀虫或控制有害生物的药剂；学习用法：环境阅读与农业话题；辨析：不只等于化肥 fertiliser","examples":[{"en":"The use of pesticides is another possible threat to the owls, though not a direct one.","zh":"农药的使用也是猫头鹰可能面临的另一种威胁，不过这种威胁并非直接作用。","sourceId":"G3","source":"original","number":30,"paragraph":"G"}],"para":"G","memory":{"method":"复合词根","parts":"pest（害虫、有害生物）＋-cide（杀灭）","tip":"针对有害生物的药剂；不要与 herbicide（除草剂）混淆。","family":"insecticide 杀虫剂；herbicide 除草剂"}},{"id":"story-c6da5c30f408","term":"threat","type":"word","ipa":"θret","pos":"n. 名词","stars":2,"zh":"威胁","contextSenses":[0],"legacyId":"threat|威胁","note":"常见义：潜在危险；学习用法：pose a threat to 对……构成威胁；辨析：possible threat 保留可能，不能改成已确定危害","examples":[{"en":"The use of pesticides is another possible threat to the owls, though not a direct one.","zh":"农药的使用也是猫头鹰可能面临的另一种威胁，不过这种威胁并非直接作用。","sourceId":"G3","source":"original","number":30,"paragraph":"G"}],"para":"G"},{"id":"story-4155ee8a93b0","term":"food chain","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"食物链","contextSenses":[0],"legacyId":"food chain|食物链","note":"常见义：生物摄食关系构成的链；学习用法：at the top of the food chain 食物链顶端；辨析：不是连锁食品店","examples":[{"en":"As moreporks are at the top of the food chain, they could be affected by an accumulative poison by consuming prey that has ingested poison.","zh":"因为 morepork 位于食物链顶端，它们可能吃到已摄入毒物的猎物，进而受到累积毒物的影响。","sourceId":"G4","source":"original","number":31,"paragraph":"G"}],"para":"G"},{"id":"story-98d8c0c54ba1","term":"ingest","type":"word","ipa":"ɪnˈdʒest","pos":"v. 动词","stars":3,"zh":"摄入毒物","contextSenses":[0],"legacyId":"ingest|摄入毒物","note":"常见义：摄入；吞入；学习用法：摄入食物或物质；辨析：区别 inject 注射，传播途径不同","examples":[{"en":"As moreporks are at the top of the food chain, they could be affected by an accumulative poison by consuming prey that has ingested poison.","zh":"因为 morepork 位于食物链顶端，它们可能吃到已摄入毒物的猎物，进而受到累积毒物的影响。","sourceId":"G4","source":"original","number":31,"paragraph":"G"}],"para":"G"},{"id":"story-fdbe61fcec5c","term":"accumulative","type":"word","ipa":"əˈkjuːmjələtɪv","pos":"adj. 形容词","stars":4,"zh":"会累积的","contextSenses":[0],"legacyId":"accumulative|会累积的","note":"常见义：累积性的；学习用法：cumulative effect 累积效应；辨析：不是一次性暴露，原文强调累积可能","examples":[{"en":"As moreporks are at the top of the food chain, they could be affected by an accumulative poison by consuming prey that has ingested poison.","zh":"因为 morepork 位于食物链顶端，它们可能吃到已摄入毒物的猎物，进而受到累积毒物的影响。","sourceId":"G4","source":"original","number":31,"paragraph":"G"}],"para":"G","memory":{"method":"词族联想","parts":"accumulate（累积）与 accumulative（会累积的）联记","tip":"毒物在食物链中累积；与一次性的影响区分。","family":"accumulation 积累；cumulative 累积的"}},{"id":"story-33c915c06950","term":"take steps","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"采取措施","contextSenses":[0],"legacyId":"take steps|采取措施","note":"常见义：采取行动；学习用法：take steps to protect… 采取措施保护；辨析：不是仅指走几步","examples":[{"en":"The New Zealand Department of Conservation is taking steps to ensure the preservation of New Zealand’s only native owl.","zh":"新西兰自然保护部门正在采取措施，确保新西兰唯一的本土猫头鹰得到保护。","sourceId":"H1","source":"original","number":32,"paragraph":"H"}],"para":"H"},{"id":"story-680f1b2f895c","term":"preservation","type":"word","ipa":"ˌprezəˈveɪʃən","pos":"n. 名词","stars":4,"zh":"保护，维持物种存续","contextSenses":[0],"legacyId":"preservation|保护，维持物种存续","note":"常见义：保护；保存；学习用法：保护物种、文物或历史遗产；辨析：本篇 preserve 侧重保护物种，与食品保存语境不同","examples":[{"en":"The New Zealand Department of Conservation is taking steps to ensure the preservation of New Zealand’s only native owl.","zh":"新西兰自然保护部门正在采取措施，确保新西兰唯一的本土猫头鹰得到保护。","sourceId":"H1","source":"original","number":32,"paragraph":"H"}],"para":"H","memory":{"method":"动词→名词","parts":"preserve 去 e，再接 -ation → preservation","tip":"preserve 保护、保存；preservation 是保护这一过程。","family":"preserve 保护；preservative 防腐剂"}},{"id":"story-a37c9391ea0c","term":"transmitter","type":"word","ipa":"trænzˈmɪtə","pos":"n. 名词","stars":3,"zh":"信号发射器","contextSenses":[0],"legacyId":"transmitter|信号发射器","note":"常见义：发射装置；学习用法：追踪动物位置或状态的装置；辨析：不同于 receiver 接收器","examples":[{"en":"The department is involved in measuring the population of moreporks and has put transmitters on a number of birds to determine survival and mortality.","zh":"该部门参与测量 morepork 的种群数量，并在若干只鸟身上安装了发射器，以确定它们的存活和死亡情况。","sourceId":"H2","source":"original","number":33,"paragraph":"H"}],"para":"H"},{"id":"story-a04330feff8a","term":"mortality","type":"word","ipa":"mɔːˈtæləti","pos":"n. 名词","stars":3,"zh":"死亡情况或死亡率","contextSenses":[0],"legacyId":"mortality|死亡情况或死亡率","note":"常见义：死亡；死亡率；学习用法：mortality rate 死亡率；辨析：morality 是道德，注意拼写","examples":[{"en":"The department is involved in measuring the population of moreporks and has put transmitters on a number of birds to determine survival and mortality.","zh":"该部门参与测量 morepork 的种群数量，并在若干只鸟身上安装了发射器，以确定它们的存活和死亡情况。","sourceId":"H2","source":"original","number":33,"paragraph":"H"}],"para":"H"},{"id":"story-ceb7ca4566e3","term":"determine","type":"word","ipa":"dɪˈtɜːmɪn","pos":"v. 动词","stars":3,"zh":"查明，确定","contextSenses":[0],"legacyId":"determine|查明，确定","note":"常见义：决定；确定；学习用法：determine survival 查明存活情况；辨析：不是部门决定鸟必须存活或死亡","examples":[{"en":"The department is involved in measuring the population of moreporks and has put transmitters on a number of birds to determine survival and mortality.","zh":"该部门参与测量 morepork 的种群数量，并在若干只鸟身上安装了发射器，以确定它们的存活和死亡情况。","sourceId":"H2","source":"original","number":33,"paragraph":"H"}],"para":"H"},{"id":"story-f16ceb631907","term":"symbolic","type":"word","ipa":"sɪmˈbɒlɪk","pos":"adj. 形容词","stars":4,"zh":"具有象征意义的","contextSenses":[0],"legacyId":"symbolic|具有象征意义的","note":"常见义：象征性的；学习用法：symbolic importance 象征意义；辨析：不是没有实际价值的同义词","examples":[{"en":"As well as being New Zealand’s only native owl, the morepork has symbolic and spiritual importance, so in monitoring the birds it is hoped that the morepork will continue to survive and thrive.","zh":"morepork 不仅是新西兰唯一的本土猫头鹰，也具有象征和精神意义；因此，人们希望通过监测，让它继续存活并繁衍兴旺。","sourceId":"H3","source":"original","number":34,"paragraph":"H"}],"para":"H","memory":{"method":"后缀构词","parts":"symbol（象征）＋-ic（形容词后缀）","tip":"动物在文化中的象征意义；不一定指真实生物学作用。","family":"symbol 象征；symbolism 象征意义"}},{"id":"story-7379024c5dc7","term":"monitor","type":"word","ipa":"ˈmɒnɪtə","pos":"v. 动词","stars":3,"zh":"持续观察监测","contextSenses":[0],"legacyId":"monitor|持续观察监测","note":"常见义：监控；监测；学习用法：monitor a population/trend 监测种群或趋势；辨析：名词 monitor 可指显示器；本句动词","examples":[{"en":"As well as being New Zealand’s only native owl, the morepork has symbolic and spiritual importance, so in monitoring the birds it is hoped that the morepork will continue to survive and thrive.","zh":"morepork 不仅是新西兰唯一的本土猫头鹰，也具有象征和精神意义；因此，人们希望通过监测，让它继续存活并繁衍兴旺。","sourceId":"H3","source":"original","number":34,"paragraph":"H"}],"para":"H"},{"id":"story-e1f9dcb7f07f","term":"thrive","type":"word","ipa":"θraɪv","pos":"v. 动词","stars":3,"zh":"繁衍兴旺","contextSenses":[0],"legacyId":"thrive|繁衍兴旺","note":"常见义：茁壮成长；繁荣；学习用法：survive and thrive 存活并发展良好；辨析：比 survive 含更良好的生存状态","examples":[{"en":"As well as being New Zealand’s only native owl, the morepork has symbolic and spiritual importance, so in monitoring the birds it is hoped that the morepork will continue to survive and thrive.","zh":"morepork 不仅是新西兰唯一的本土猫头鹰，也具有象征和精神意义；因此，人们希望通过监测，让它继续存活并繁衍兴旺。","sourceId":"H3","source":"original","number":34,"paragraph":"H"}],"para":"H"},{"id":"story-375e258171ab","term":"claim","type":"word","ipa":"kleɪm","pos":"v. 动词","stars":2,"zh":"宣示占有领地","contextSenses":[0],"legacyId":"claim|宣示占有领地","note":"常见义：声称；要求；认领；学习用法：claim territory 宣示领地；claim that 声称；辨析：此处不是提出论文观点","examples":[{"en":"At dusk, the melancholy sound of the morepork can be heard in forests and parks as it calls to other moreporks and claims territory.","zh":"黄昏时，森林和公园里能听到 morepork 忧伤的叫声，它在呼唤其他同类并宣示领地。","sourceId":"I1","source":"original","number":35,"paragraph":"I"}],"para":"I"},{"id":"story-acc4161b1182","term":"melancholy","type":"word","ipa":"ˈmelənkəli","pos":"adj. 形容词","stars":3,"zh":"忧伤的，听来哀婉的","contextSenses":[0],"legacyId":"melancholy|忧伤的，听来哀婉的","note":"常见义：忧郁；忧伤；学习用法：描述声音或情绪；辨析：是作者对声音的描述，不是鸟患抑郁症","examples":[{"en":"At dusk, the melancholy sound of the morepork can be heard in forests and parks as it calls to other moreporks and claims territory.","zh":"黄昏时，森林和公园里能听到 morepork 忧伤的叫声，它在呼唤其他同类并宣示领地。","sourceId":"I1","source":"original","number":35,"paragraph":"I"}],"para":"I"},{"id":"story-1cf3dceec6ce","term":"echo","type":"word","ipa":"ˈekəʊ","pos":"v. 动词","stars":3,"zh":"呼应，模仿声音","contextSenses":[0],"legacyId":"echo|呼应，模仿声音","note":"常见义：回声；重复；呼应；学习用法：echo an idea 呼应观点；辨析：本句动词，不是名词一阵回声","examples":[{"en":"Its Māori name (ruru) echoes its two-part cry.","zh":"它的毛利语名字 ruru，呼应了由两个音节或两部分组成的叫声。","sourceId":"I2","source":"original","number":36,"paragraph":"I"}],"para":"I"},{"id":"story-d345bc3d1f2b","term":"cry","type":"word","ipa":"kraɪ","pos":"n. 名词","stars":2,"zh":"鸟的叫声","contextSenses":[0],"legacyId":"cry|鸟的叫声","note":"常见义：哭泣；叫喊；鸣叫；学习用法：animal cry 动物叫声；辨析：不是每次 cry 都是哭泣","examples":[{"en":"Its Māori name (ruru) echoes its two-part cry.","zh":"它的毛利语名字 ruru，呼应了由两个音节或两部分组成的叫声。","sourceId":"I2","source":"original","number":36,"paragraph":"I"}],"para":"I"},{"id":"story-2a7bcb5be3df","term":"guardian","type":"word","ipa":"ˈɡɑːdiən","pos":"n. 名词","stars":3,"zh":"守护者","contextSenses":[0],"legacyId":"guardian|守护者","note":"常见义：保护者；监护人；学习用法：文化象征或法定监护人；辨析：此处不是法律身份","examples":[{"en":"In the tradition of the Māori people of New Zealand, the morepork, or ruru, was often seen as a careful guardian.","zh":"在新西兰毛利人的传统中，morepork 或 ruru，常被视为谨慎警觉的守护者。","sourceId":"I3","source":"original","number":37,"paragraph":"I"}],"para":"I"},{"id":"story-082c00db8520","term":"see as","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"视为","contextSenses":[0],"legacyId":"see as|视为","note":"常见义：把……看作；学习用法：be seen as 被认为是；辨析：不是看见某物像另一个物体","examples":[{"en":"In the tradition of the Māori people of New Zealand, the morepork, or ruru, was often seen as a careful guardian.","zh":"在新西兰毛利人的传统中，morepork 或 ruru，常被视为谨慎警觉的守护者。","sourceId":"I3","source":"original","number":37,"paragraph":"I"}],"para":"I"},{"id":"story-1328a326198b","term":"saying","type":"word","ipa":"ˈseɪɪŋ","pos":"n. 名词","stars":2,"zh":"谚语，俗语","contextSenses":[0],"legacyId":"saying|谚语，俗语","note":"常见义：格言；说法；学习用法：traditional saying 传统谚语；辨析：不是说话动作的现在分词","examples":[{"en":"A number of sayings referred to the bird’s alertness.","zh":"若干谚语提及这种鸟的警觉性。","sourceId":"I4","source":"original","number":38,"paragraph":"I"}],"para":"I"},{"id":"story-fafd7fd2bbd7","term":"alertness","type":"word","ipa":"əˈlɜːtnəs","pos":"n. 名词","stars":3,"zh":"警觉性","contextSenses":[0],"legacyId":"alertness|警觉性","note":"常见义：警惕；敏锐注意；学习用法：动物感官或注意状态；辨析：与B2动词 alert 使警觉同词族，但词性不同","examples":[{"en":"A number of sayings referred to the bird’s alertness.","zh":"若干谚语提及这种鸟的警觉性。","sourceId":"I4","source":"original","number":38,"paragraph":"I"}],"para":"I"},{"id":"story-07e270eee7b4","term":"associate with","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"与……联系起来","contextSenses":[0],"legacyId":"associate with|与……联系起来","note":"常见义：联系；交往；学习用法：be associated with 与……相关；辨析：相关不等于证明因果","examples":[{"en":"As a bird of the night, it was associated with the spirit world.","zh":"作为夜间活动的鸟，它与灵界联系在一起。","sourceId":"I5","source":"original","number":39,"paragraph":"I"}],"para":"I"},{"id":"story-f0e3745033ef","term":"spirit","type":"word","ipa":"ˈspɪrɪt","pos":"n. 名词","stars":2,"zh":"灵界中的灵或神灵","contextSenses":[0],"legacyId":"spirit|灵界中的灵或神灵","note":"常见义：精神；灵魂；神灵；学习用法：spirit world 灵界；team spirit 团队精神；辨析：本句不是团队士气，也不是酒精饮品 spirits","examples":[{"en":"As a bird of the night, it was associated with the spirit world.","zh":"作为夜间活动的鸟，它与灵界联系在一起。","sourceId":"I5","source":"original","number":39,"paragraph":"I"}],"para":"I"},{"id":"story-0e909164dbaa","term":"messenger","type":"word","ipa":"ˈmesɪndʒə","pos":"n. 名词","stars":3,"zh":"信使","contextSenses":[0],"legacyId":"messenger|信使","note":"常见义：传递信息者；学习用法：文化信使；通信角色；辨析：不是仅指聊天软件名称","examples":[{"en":"Moreporks were believed to act as messengers to the gods in the heavens, flying along spiritual paths in the sky.","zh":"人们相信，morepork 会充当通往天上诸神的信使，沿天空中的精神路径飞行。","sourceId":"I6","source":"original","number":40,"paragraph":"I"}],"para":"I"},{"id":"story-355eaa0c0ee9","term":"act as","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"充当","contextSenses":[0],"legacyId":"act as|充当","note":"常见义：担任；发挥……作用；学习用法：act as a bridge 充当桥梁；辨析：不一定含表演扮演之意","examples":[{"en":"Moreporks were believed to act as messengers to the gods in the heavens, flying along spiritual paths in the sky.","zh":"人们相信，morepork 会充当通往天上诸神的信使，沿天空中的精神路径飞行。","sourceId":"I6","source":"original","number":40,"paragraph":"I"}],"para":"I"},{"id":"story-527932f3df7f","term":"medium","type":"word","ipa":"ˈmiːdiəm","pos":"n. 名词","stars":3,"zh":"沟通媒介","contextSenses":[0],"legacyId":"medium|沟通媒介","note":"常见义：媒介；中等的；灵媒；学习用法：communication medium 传播媒介；辨析：这里 mediums 指神灵沟通媒介或灵媒；大众传播媒介复数常用 media","examples":[{"en":"They were the mediums used to communicate with the gods.","zh":"它们是人们用来与诸神沟通的媒介。","sourceId":"I7","source":"original","number":41,"paragraph":"I"}],"para":"I"},{"id":"story-c9f064b276f2","term":"communicate with","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"与……沟通","contextSenses":[0],"legacyId":"communicate with|与……沟通","note":"常见义：交流；传达；学习用法：与人交流；communicate information 传递信息；辨析：communicate with 接对象，communicate sth 接内容","examples":[{"en":"They were the mediums used to communicate with the gods.","zh":"它们是人们用来与诸神沟通的媒介。","sourceId":"I7","source":"original","number":41,"paragraph":"I"}],"para":"I"},{"id":"story-0968cde55e2c","term":"signify","type":"word","ipa":"ˈsɪɡnɪfaɪ","pos":"v. 动词","stars":3,"zh":"象征，表示","contextSenses":[0],"legacyId":"signify|象征，表示","note":"常见义：表示；意味着；学习用法：某符号或现象传达意义；辨析：文化象征不等于科学预测","examples":[{"en":"The occasional high, piercing call of the morepork signified bad news, but the lower-pitched and more common “ruru” call heralded good news.","zh":"morepork 偶尔发出的高亢尖锐叫声象征坏消息，而音调较低、更常见的 ruru 叫声则预示好消息。","sourceId":"I8","source":"original","number":42,"paragraph":"I"}],"para":"I"},{"id":"story-49f2a73b4402","term":"herald","type":"word","ipa":"ˈherəld","pos":"v. 动词","stars":3,"zh":"预示，宣告到来","contextSenses":[0],"legacyId":"herald|预示，宣告到来","note":"常见义：预告；预示；学习用法：herald a new era 预示新时代；辨析：本句不是鸟真的播报新闻","examples":[{"en":"The occasional high, piercing call of the morepork signified bad news, but the lower-pitched and more common “ruru” call heralded good news.","zh":"morepork 偶尔发出的高亢尖锐叫声象征坏消息，而音调较低、更常见的 ruru 叫声则预示好消息。","sourceId":"I8","source":"original","number":42,"paragraph":"I"}],"para":"I"},{"id":"story-bb48d76ff691","term":"piercing","type":"word","ipa":"ˈpɪəsɪŋ","pos":"adj. 形容词","stars":3,"zh":"高而尖锐的","contextSenses":[0],"legacyId":"piercing|高而尖锐的","note":"常见义：刺耳的；穿透的；学习用法：piercing sound 刺耳声音；辨析：pierce 动词为刺穿，此处描述听觉","examples":[{"en":"The occasional high, piercing call of the morepork signified bad news, but the lower-pitched and more common “ruru” call heralded good news.","zh":"morepork 偶尔发出的高亢尖锐叫声象征坏消息，而音调较低、更常见的 ruru 叫声则预示好消息。","sourceId":"I8","source":"original","number":42,"paragraph":"I"}],"para":"I"},{"id":"story-517e6662c6f2","term":"adapt to","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"适应","contextSenses":[0],"note":"不及物用法加to；adapt sth to do为调整某物以做到……。 由原句提炼或迁移；具体例句与原文形式可能不同。","para":"A","examples":[{"en":"Where other native birds suffered from predation by the Polynesian rat, the laughing owl turned the tables and adapted its diet to include the rodent.","zh":"其他本土鸟类遭受波利尼西亚鼠捕食时，笑鸮却扭转了局面，调整食谱，把这种啮齿动物也纳入了猎物。","sourceId":"A3","source":"original","number":3,"paragraph":"A"},{"en":"Some birds adapt well to urban environments.","zh":"有些鸟很能适应城市环境。","added":true,"source":"supplemental","number":null}]},{"id":"story-0115b478cd9b","term":"manage to survive","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"成功存活","contextSenses":[0],"note":"manage to含成功完成，不能只译成尝试。 由原句提炼或迁移；具体例句与原文形式可能不同。","para":"A","examples":[{"en":"Surprisingly, it is the smaller owl, the morepork, that has managed to survive until this day.","zh":"令人意外的是，成功存活至今的反而是体型较小的猫头鹰 morepork。","sourceId":"A6","source":"original","number":6,"paragraph":"A"},{"en":"The species managed to survive despite habitat changes.","zh":"尽管栖息地变化，该物种仍成功存活。","added":true,"source":"supplemental","number":null}]},{"id":"story-e0e6bc57d095","term":"pose a threat to","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"对……构成威胁","contextSenses":[0],"note":"阅读原文 threat to 可迁移为完整动词搭配。 由原句提炼或迁移；具体例句与原文形式可能不同。","para":"G","examples":[{"en":"The use of pesticides is another possible threat to the owls, though not a direct one.","zh":"农药的使用也是猫头鹰可能面临的另一种威胁，不过这种威胁并非直接作用。","sourceId":"G3","source":"original","number":30,"paragraph":"G"},{"en":"Pollution poses a threat to wildlife.","zh":"污染威胁野生动物。","added":true,"source":"supplemental","number":null}]},{"id":"story-ecfd1b884aa9","term":"take steps to","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"采取措施","contextSenses":[0],"note":"后接行动目的，强调开始实施措施。 由原句提炼或迁移；具体例句与原文形式可能不同。","para":"H","examples":[{"en":"The New Zealand Department of Conservation is taking steps to ensure the preservation of New Zealand’s only native owl.","zh":"新西兰自然保护部门正在采取措施，确保新西兰唯一的本土猫头鹰得到保护。","sourceId":"H1","source":"original","number":32,"paragraph":"H"},{"en":"The government is taking steps to protect wildlife.","zh":"政府正在采取措施保护野生动物。","added":true,"source":"supplemental","number":null}]}],"sentences":[{"id":"story-A1","sourceId":"A1","en":"As an island country with a fauna dominated by birds, New Zealand was once home to an owl species which is now extinct, the laughing owl, named for its distinctive cry.","zh":"新西兰是一个鸟类占动物群主体的岛国，那里曾生活着一种如今已经灭绝的猫头鹰——笑鸮，它因独特的叫声而得名。","para":"A","note":"主干 New Zealand was once home to an owl species。As an island country… 是身份背景；with a fauna dominated by birds 中 dominated 为被动修饰。which is now extinct 修饰 species；the laughing owl 为同位语；named for… 是省略 which was 的被动修饰。时间对照 once 与 now 很重要。","paragraph":"A"},{"id":"story-A2","sourceId":"A2","en":"This bird was widespread throughout the islands when European settlers arrived in the middle of the 19th century and it remained in good numbers for some years thereafter.","zh":"十九世纪中叶欧洲移民到来时，这种鸟广泛分布于各岛，之后的若干年里数量仍然可观。","para":"A","note":"when 从句定位欧洲移民到来时；两个主句谓语 was 与 remained 描述分布和数量。for some years 只限定若干年，不代表永远如此。","paragraph":"A"},{"id":"story-A3","sourceId":"A3","en":"Where other native birds suffered from predation by the Polynesian rat, the laughing owl turned the tables and adapted its diet to include the rodent.","zh":"其他本土鸟类遭受波利尼西亚鼠捕食时，笑鸮却扭转了局面，调整食谱，把这种啮齿动物也纳入了猎物。","para":"A","note":"核心对比：Where A suffered…, B turned the tables…。Where 这里表示情况对照，可理解为“其他鸟……，而笑鸮却……”，不是仅问地点。adapted its diet to include… 中 to include 表调整后把鼠纳入食谱。不能把 other native birds 的遭遇移到 laughing owl 身上。","paragraph":"A"},{"id":"story-A4","sourceId":"A4","en":"It was also capable of catching and killing the other New Zealand owl, the morepork, and even larger birds, such as the weka.","zh":"它还能捕捉并杀死新西兰另一种猫头鹰 morepork，甚至捕食更大的鸟，例如 weka。","para":"A","note":"本句重点词补充：catch 捕获，kill 杀死，larger 更大的，weka 一种新西兰鸟。the morepork 为 the other New Zealand owl 的同位语。捕杀能力本身不能严格证明体型更大；体型证据在A6。","paragraph":"A"},{"id":"story-A5","sourceId":"A5","en":"However, the laughing owl was wiped out around the beginning of the 20th century, its demise caused by specimen collectors, habitat changes, and non-native predators including cats and stoats.","zh":"然而，笑鸮在二十世纪初前后灭绝了，它的消亡由标本采集者、栖息地变化，以及包括猫和白鼬在内的非本土捕食者造成。","para":"A","note":"主干 the laughing owl was wiped out…；its demise caused by… 为独立主格，结构为“名词 + 过去分词”，相当于补充 its demise was caused by…。列出三类因素，不含波利尼西亚鼠作为已明确导致该物种灭绝的原因。","paragraph":"A"},{"id":"story-A6","sourceId":"A6","en":"Surprisingly, it is the smaller owl, the morepork, that has managed to survive until this day.","zh":"令人意外的是，成功存活至今的反而是体型较小的猫头鹰 morepork。","para":"A","note":"核心强调句：It is [the smaller owl, the morepork] that has managed to survive…。还原为 The smaller owl… has managed to survive。smaller 的对照对象是前文 laughing owl，因此能推得笑鸮较大。不能因为缺少 larger than 字样就判 NOT GIVEN。","paragraph":"A"},{"id":"story-B1","sourceId":"B1","en":"Speckled dark brown, with yellow eyes and long tails, they are around 29 centimetres long from head to tail and 175 grams in weight.","zh":"它们有带深棕色斑点的羽毛、黄色眼睛和长尾巴，从头到尾长约二十九厘米，重约一百七十五克。","para":"B","note":"Speckled dark brown… 为补充外观描述；主干 they are… long and… in weight。they 指 moreporks，不是已灭绝的笑鸮。around 为约数。","paragraph":"B"},{"id":"story-B2","sourceId":"B2","en":"Moreporks have fringes on the edge of their feathers, so they can fly almost silently and not alert potential prey.","zh":"morepork 的羽毛边缘有流苏状结构，因此它们飞行时几乎无声，不会惊动潜在猎物。","para":"B","note":"so 表结果；can fly… and not alert… 并列动作，共用 can。almost silently 不是绝对无声，potential prey 是可能成为猎物的动物。","paragraph":"B"},{"id":"story-B3","sourceId":"B3","en":"They have acute hearing and their large eyes are very sensitive to light.","zh":"它们听觉敏锐，大大的眼睛也对光线十分敏感。","para":"B","note":"and 连接两个完整分句。very 修饰 sensitive，不是 eyes；大眼睛与感光能力是不同特征。","paragraph":"B"},{"id":"story-C1","sourceId":"C1","en":"Moreporks nest in tree hollows, in clumps of plants, or in cavities among rocks and roots.","zh":"morepork 在树洞、植物丛，或岩石与树根之间的洞穴中筑巢。","para":"C","note":"三个 in… 表并列巢址；clump 为一丛，cavity 为洞穴。不是只在树洞筑巢。","paragraph":"C"},{"id":"story-C2","sourceId":"C2","en":"In the wild, moreporks usually start nesting in October, although two specimens have been recorded nesting in mid-winter, possibly stimulated by an ample food supply.","zh":"在野外，morepork 通常十月开始筑巢；不过，有记录显示两个个体在隆冬筑巢，可能是受到充足食物供应的促使。","para":"C","note":"主句 usually start…，although 引出例外；two specimens 指两个个体，不是两份死标本。possibly stimulated… 修饰冬季筑巢的个体或其行为，原因只属可能，不能说已确证。","paragraph":"C"},{"id":"story-C3","sourceId":"C3","en":"The female lays up to three white eggs, which she incubates for 20 to 30 days.","zh":"雌鸟最多产下三枚白色的卵，随后孵化二十到三十天。","para":"C","note":"which 指 eggs；up to three 是上限，不是每次恰好三枚；20 to 30 days 是孵化时长范围。","paragraph":"C"},{"id":"story-C4","sourceId":"C4","en":"During this time, she rarely hunts, and the male brings food to her.","zh":"在这段时间里，雌鸟很少捕猎，雄鸟会把食物带给它。","para":"C","note":"this time 指孵卵的20至30天；she/her 指雌鸟，the male 指雄鸟。代词识别决定谁供食。","paragraph":"C"},{"id":"story-D1","sourceId":"D1","en":"Once the chicks hatch, she stays mainly on the nest until the young owls are fully feathered.","zh":"雏鸟一旦孵化，雌鸟就主要待在巢上，直到幼鸟羽毛完全长齐。","para":"D","note":"Once 引导起始条件或时间，until 引出终点。she 指雌鸟；fully feathered 不等于一定已经会飞，会飞的日期另见D4。","paragraph":"D"},{"id":"story-D2","sourceId":"D2","en":"When hatched, chicks are covered in light grey down and have their eyes closed.","zh":"刚孵化时，雏鸟覆盖着浅灰色绒毛，眼睛闭着。","para":"D","note":"When hatched＝When they are hatched；have their eyes closed 为“have + 宾语 + 过去分词补语”，描述眼睛的状态，不能拆成 have closed 的完成时。","paragraph":"D"},{"id":"story-D3","sourceId":"D3","en":"The eyes do not open until the eighth day after hatching.","zh":"它们要到孵化后的第八天才睁眼。","para":"D","note":"The eyes do not open until… 为延迟发生；否定涵盖第八天以前，不能把事件时间推为第八天之后的任意一天。","paragraph":"D"},{"id":"story-D4","sourceId":"D4","en":"They can fly at around 35 days.","zh":"它们大约在三十五日龄时就能飞行。","para":"D","note":"at around 35 days 指出壳后的约35日龄，不是持续飞行35天。","paragraph":"D"},{"id":"story-E1","sourceId":"E1","en":"By day, moreporks sleep in roosts.","zh":"白天，morepork 在栖息处睡觉。","para":"E","note":"简短主谓结构；先建昼夜对照，和下一句一起理解。","paragraph":"E"},{"id":"story-E2","sourceId":"E2","en":"By night, they hunt a variety of animals – mainly large invertebrates including scarab and huhu beetles, moths, caterpillars and spiders.","zh":"夜晚，它们捕食多种动物，主要是大型无脊椎动物，包括金龟子、huhu 甲虫、蛾、毛毛虫和蜘蛛。","para":"E","note":"破折号后具体说明食物主体；including 表举例，不是完整封闭名单。昆虫名以认读定位为主，不需要全部用于口语输出。","paragraph":"E"},{"id":"story-E3","sourceId":"E3","en":"They also take small birds and mice.","zh":"它们也捕食小鸟和老鼠。","para":"E","note":"They 指 moreporks；与前句一起防止误判“只吃昆虫”。mice 是 mouse 的复数。","paragraph":"E"},{"id":"story-E4","sourceId":"E4","en":"They can find suitable food in pine forest as well as native forest.","zh":"它们既能在松林中，也能在本土森林中找到合适的食物。","para":"E","note":"pine forest 与 native forest 都是可觅食环境；can 表有能力，不宣称两者食物数量完全相等。","paragraph":"E"},{"id":"story-E5","sourceId":"E5","en":"A morepork uses its sharp talons to catch or stun its prey, which it then carries away in its bill.","zh":"一只 morepork 用锋利的爪子抓住或击晕猎物，随后用喙把猎物叼走。","para":"E","note":"which 指 prey；it 指 morepork。uses talons to… 与 carries… in its bill 指两种不同器官的功能，不能说用喙击晕猎物。","paragraph":"E"},{"id":"story-E6","sourceId":"E6","en":"Moreporks are clever hunters, and birds such as robins, grey warblers and fantails can end up as their prey.","zh":"morepork 是善于捕猎的鸟，知更鸟、灰莺、扇尾鹟等鸟类都可能最终成为它们的猎物。","para":"E","note":"such as 后为例子；can end up 不表示所有这些鸟都必然被捕食。","paragraph":"E"},{"id":"story-E7","sourceId":"E7","en":"In the day, these small birds sometimes mob drowsy moreporks and chase them away from their roosts; they force the sleepy predators to search for a more peaceful spot.","zh":"白天，这些小鸟有时会集群围攻昏昏欲睡的 morepork，把它们赶离栖息处，迫使这些困倦的捕食者寻找更安静的地方。","para":"E","note":"these small birds 是主动驱赶者；them 指 moreporks。分号后 they 仍指小鸟，predators 指猫头鹰。force sb to do 为强迫某人做，sometimes 限定偶尔发生。","paragraph":"E"},{"id":"story-F1","sourceId":"F1","en":"Moreporks have proved to be ungracious hosts.","zh":"事实证明，morepork 并不是好客的主人。","para":"F","note":"ungracious 意为不友善、不好客。此句为下一段案例设悬念，不能按人类礼貌标准解释动物道德。","paragraph":"F"},{"id":"story-F2","sourceId":"F2","en":"Scientists trying to establish a population of plovers on Motuora Island in New Zealand’s Hauraki Gulf were mystified as to why only two birds survived out of the 75 placed there.","zh":"科学家试图在新西兰豪拉基湾的莫图奥拉岛建立一个鸻类种群；他们不解的是，放到那里的七十五只鸟为何只有两只存活。","para":"F","note":"长句主干 Scientists were mystified。trying to establish… 修饰 Scientists；as to why… 引出困惑内容，其中 only two birds survived 是核心。placed there 修饰 the 75，省略 birds which were。保留 only two 与总数75的关系；原文未在此句单独交代所有其他鸟的最终去向。","paragraph":"F"},{"id":"story-F3","sourceId":"F3","en":"The culprits turned out to be five pairs of moreporks that ate or chased away the new arrivals.","zh":"原来，罪魁祸首是五对 morepork，它们吃掉或赶走了这些新来的鸟。","para":"F","note":"that 修饰 five pairs of moreporks。ate or chased away 保留两种结果，不能把全部73只都判成被吃掉；five pairs 是十只，不是五只。","paragraph":"F"},{"id":"story-G1","sourceId":"G1","en":"Although moreporks are still considered to be relatively common, it is likely that numbers are in gradual decline due to predation and loss of habitat.","zh":"尽管 morepork 仍被认为比较常见，但它们的数量很可能正因捕食与栖息地丧失而逐渐下降。","para":"G","note":"Although 承认目前仍较常见；it is likely that… 为概率判断。numbers 指种群数量，不是每只猫头鹰的体重或个体大小。","paragraph":"G"},{"id":"story-G2","sourceId":"G2","en":"As the female is a hole-nester, she is vulnerable to predators such as stoats and possums during the breeding season, and eggs and chicks will also be at risk from rats.","zh":"由于雌鸟在洞穴中筑巢，它在繁殖季节容易遭到白鼬和负鼠等捕食者袭击，卵和雏鸟也会受到鼠类威胁。","para":"G","note":"As 在此表示原因，不是“作为”。主句两部分：she is vulnerable… 和 eggs and chicks will…；hole-nester 指在洞穴中筑巢的鸟，不表示鸟永远不能飞出洞。","paragraph":"G"},{"id":"story-G3","sourceId":"G3","en":"The use of pesticides is another possible threat to the owls, though not a direct one.","zh":"农药的使用也是猫头鹰可能面临的另一种威胁，不过这种威胁并非直接作用。","para":"G","note":"though not a direct one 为省略让步结构，one 代替 threat。下一句解释间接路径，不应仅凭 not direct 判无影响。","paragraph":"G"},{"id":"story-G4","sourceId":"G4","en":"As moreporks are at the top of the food chain, they could be affected by an accumulative poison by consuming prey that has ingested poison.","zh":"因为 morepork 位于食物链顶端，它们可能吃到已摄入毒物的猎物，进而受到累积毒物的影响。","para":"G","note":"As 表原因；could be affected 是情态被动，只说可能。by consuming… 表途径；that has ingested poison 修饰 prey。意义链为“毒物→猎物摄入→猫头鹰捕食→可能累积受影响”，不是猫头鹰主动吃农药。输出建议用更自然的 toxins can accumulate through the food chain。","paragraph":"G"},{"id":"story-H1","sourceId":"H1","en":"The New Zealand Department of Conservation is taking steps to ensure the preservation of New Zealand’s only native owl.","zh":"新西兰自然保护部门正在采取措施，确保新西兰唯一的本土猫头鹰得到保护。","para":"H","note":"is taking steps 表正在进行的行动；to ensure… 是目的。“唯一”应结合A段理解为原文叙述时仍存活的本土猫头鹰。","paragraph":"H"},{"id":"story-H2","sourceId":"H2","en":"The department is involved in measuring the population of moreporks and has put transmitters on a number of birds to determine survival and mortality.","zh":"该部门参与测量 morepork 的种群数量，并在若干只鸟身上安装了发射器，以确定它们的存活和死亡情况。","para":"H","note":"主句有 is involved… 和 has put… 两个谓语，时态不同。a number of 是若干；to determine 表目的。不能把“安装发射器”直接说成已经确保全部鸟存活。","paragraph":"H"},{"id":"story-H3","sourceId":"H3","en":"As well as being New Zealand’s only native owl, the morepork has symbolic and spiritual importance, so in monitoring the birds it is hoped that the morepork will continue to survive and thrive.","zh":"morepork 不仅是新西兰唯一的本土猫头鹰，也具有象征和精神意义；因此，人们希望通过监测，让它继续存活并繁衍兴旺。","para":"H","note":"As well as being… 为前置补充，逻辑主语 the morepork；so 后 it is hoped that… 是非人称被动表达愿望。in monitoring the birds 可理解为在监测工作中，不能当作已证实的成功结论。","paragraph":"H"},{"id":"story-I1","sourceId":"I1","en":"At dusk, the melancholy sound of the morepork can be heard in forests and parks as it calls to other moreporks and claims territory.","zh":"黄昏时，森林和公园里能听到 morepork 忧伤的叫声，它在呼唤其他同类并宣示领地。","para":"I","note":"as 引出发声时的行为；it calls… and claims… 为并列谓语。can be heard 是情态被动。","paragraph":"I"},{"id":"story-I2","sourceId":"I2","en":"Its Māori name (ruru) echoes its two-part cry.","zh":"它的毛利语名字 ruru，呼应了由两个音节或两部分组成的叫声。","para":"I","note":"Its 指 morepork；two-part 指叫声结构，不能推成两只鸟一起叫。","paragraph":"I"},{"id":"story-I3","sourceId":"I3","en":"In the tradition of the Māori people of New Zealand, the morepork, or ruru, was often seen as a careful guardian.","zh":"在新西兰毛利人的传统中，morepork 或 ruru，常被视为谨慎警觉的守护者。","para":"I","note":"was often seen as 是文化观念归属，often 表经常。or ruru 是同名解释，不是另一物种。","paragraph":"I"},{"id":"story-I4","sourceId":"I4","en":"A number of sayings referred to the bird’s alertness.","zh":"若干谚语提及这种鸟的警觉性。","para":"I","note":"referred to 本句为提及，与 refer to as 称为不同。A number of 后接复数，谓语 referred 不受数量问题影响。","paragraph":"I"},{"id":"story-I5","sourceId":"I5","en":"As a bird of the night, it was associated with the spirit world.","zh":"作为夜间活动的鸟，它与灵界联系在一起。","para":"I","note":"As a bird of the night 表身份背景。was associated with 描述文化联想，不是生物学证实。","paragraph":"I"},{"id":"story-I6","sourceId":"I6","en":"Moreporks were believed to act as messengers to the gods in the heavens, flying along spiritual paths in the sky.","zh":"人们相信，morepork 会充当通往天上诸神的信使，沿天空中的精神路径飞行。","para":"I","note":"核心句式：S was believed to do…，等于 People believed that S did…。flying along… 补充文化描绘。把 was believed 保留下来，不译成鸟确实替神传信。","paragraph":"I"},{"id":"story-I7","sourceId":"I7","en":"They were the mediums used to communicate with the gods.","zh":"它们是人们用来与诸神沟通的媒介。","para":"I","note":"used to communicate 是过去分词修饰 mediums，可还原 which were used to communicate；不是 used to do 过去常常。后者须有作为谓语的 used，不能看到 used to 就统一套义。","paragraph":"I"},{"id":"story-I8","sourceId":"I8","en":"The occasional high, piercing call of the morepork signified bad news, but the lower-pitched and more common “ruru” call heralded good news.","zh":"morepork 偶尔发出的高亢尖锐叫声象征坏消息，而音调较低、更常见的 ruru 叫声则预示好消息。","para":"I","note":"but 对比两种叫声与象征意义。occasional 是偶尔，more common 是相对更常见；lower-pitched 为音调更低。先分清高低，再分清坏好，避免把对照配对颠倒。","paragraph":"I"}],"examples":[{"en":"Some birds adapt well to urban environments.","zh":"有些鸟很能适应城市环境。","added":true},{"en":"Students need time to adapt to a new culture.","zh":"学生需要时间适应新文化。","added":true},{"en":"Employees must adapt to changing technology.","zh":"员工必须适应变化的技术。","added":true},{"en":"The owl adapted its diet to include new prey.","zh":"猫头鹰调整食谱，纳入新猎物。","added":true},{"en":"The species managed to survive despite habitat changes.","zh":"尽管栖息地变化，该物种仍成功存活。","added":true},{"en":"The birds managed to survive through a harsh winter.","zh":"这些鸟成功度过严冬。","added":true},{"en":"The tree managed to survive in dry conditions.","zh":"这棵树在干旱条件下成功存活。","added":true},{"en":"The small business managed to survive during the recession.","zh":"小企业在衰退中成功维持经营。","added":true},{"en":"Owls are sensitive to light.","zh":"猫头鹰对光敏感。","added":true},{"en":"My eyes are sensitive to bright light.","zh":"我的眼睛对强光敏感。","added":true},{"en":"Some plants are sensitive to temperature changes.","zh":"有些植物对温度变化敏感。","added":true},{"en":"Teachers should be sensitive to students' needs.","zh":"教师应关注学生的需要。","added":true},{"en":"Young birds are vulnerable to predators.","zh":"幼鸟容易遭捕食者袭击。","added":true},{"en":"Coastal cities are vulnerable to flooding.","zh":"沿海城市容易遭受洪水。","added":true},{"en":"Small populations are vulnerable to habitat loss.","zh":"较小种群容易受到栖息地丧失影响。","added":true},{"en":"Young animals are vulnerable to disease.","zh":"幼小动物容易患病。","added":true},{"en":"Pollution poses a threat to wildlife.","zh":"污染威胁野生动物。","added":true},{"en":"Habitat loss poses a threat to native birds.","zh":"栖息地丧失威胁本土鸟类。","added":true},{"en":"Pesticides can pose a threat to animals in the food chain.","zh":"农药可威胁食物链中的动物。","added":true},{"en":"Non-native predators can pose a threat to nesting birds.","zh":"非本土捕食者可能威胁筑巢的鸟。","added":true},{"en":"The government is taking steps to protect wildlife.","zh":"政府正在采取措施保护野生动物。","added":true},{"en":"I am taking steps to improve my pronunciation.","zh":"我正在采取措施改善发音。","added":true},{"en":"The school is taking steps to reduce food waste.","zh":"学校正在采取措施减少食物浪费。","added":true},{"en":"Scientists are taking steps to monitor the population.","zh":"科学家正在采取措施监测种群。","added":true}],"questions":[],"references":[]};
